"""Frozen contract-first, three-language vertical-slice benchmark.

These are ten newly authored mini-app specifications, NOT an independent
third-party full-stack benchmark. Public tests guide candidate selection;
holdout cases are never included in model prompts, search, or repairs.
"""
from __future__ import annotations

import hashlib
import json


# Public and holdout inputs deliberately differ. All expected values are
# manually specified and verified by contract tests rather than generated by
# the model being evaluated.
APPS = [
    ("invoice", "Invoice total", "sum item.price * item.qty for each item in payload.items; empty items means zero", "number",
     [({"items": [{"price": 4, "qty": 3}, {"price": 5, "qty": 2}]}, 22), ({"items": []}, 0)],
     [({"items": [{"price": 0, "qty": 9}, {"price": 12, "qty": 2}]}, 24), ({"items": [{"price": 7, "qty": 1}]}, 7)]),
    ("slug", "Normalized slug", "lowercase payload.text, trim it, collapse all whitespace runs to one hyphen", "string",
     [({"text": "  Hello   World "}, "hello-world"), ({"text": "API Server"}, "api-server")],
     [({"text": "Multiple\tSpaces"}, "multiple-spaces"), ({"text": ""}, "")]),
    ("discount", "Discounted price", "integer floor of payload.amount * (100 - payload.percent) / 100", "number",
     [({"amount": 100, "percent": 20}, 80), ({"amount": 50, "percent": 0}, 50)],
     [({"amount": 125, "percent": 20}, 100), ({"amount": 99, "percent": 50}, 49)]),
    ("filter", "Matching values", "list of payload.numbers that are greater than or equal to payload.minimum, preserving input order", "list",
     [({"numbers": [1, 5, 8], "minimum": 5}, [5, 8]), ({"numbers": [], "minimum": 2}, [])],
     [({"numbers": [-4, 0, 3, -1], "minimum": -1}, [0, 3, -1]), ({"numbers": [2, 2, 3], "minimum": 2}, [2, 2, 3])]),
    ("progress", "Progress percent", "integer floor of 100 * payload.done / payload.total; return 0 if total is zero", "number",
     [({"done": 3, "total": 4}, 75), ({"done": 0, "total": 0}, 0)],
     [({"done": 2, "total": 3}, 66), ({"done": 4, "total": 5}, 80)]),
    ("vowels", "Vowel count", "count letters a,e,i,o,u in payload.text, ignoring case", "number",
     [({"text": "Apple"}, 2), ({"text": "sky"}, 0)],
     [({"text": "education"}, 5), ({"text": "AEIOU"}, 5)]),
    ("fahrenheit", "Fahrenheit", "round payload.celsius * 9 / 5 + 32 to the nearest integer", "number",
     [({"celsius": 0}, 32), ({"celsius": 100}, 212)],
     [({"celsius": -40}, -40), ({"celsius": 20}, 68)]),
    ("unique", "Unique tags", "deduplicate strings in payload.tags while preserving their first-seen order", "list",
     [({"tags": ["a", "b", "a"]}, ["a", "b"]), ({"tags": []}, [])],
     [({"tags": ["x", "x", "y", "z", "y"]}, ["x", "y", "z"]), ({"tags": ["one"]}, ["one"])]),
    ("maximum", "Maximum value", "maximum of payload.numbers, returning null (Python None) for an empty list", "nullable-number",
     [({"numbers": [2, 9, -1]}, 9), ({"numbers": []}, None)],
     [({"numbers": [-7, -2, -10]}, -2), ({"numbers": [0]}, 0)]),
    ("words", "Word count", "number of whitespace-separated words in payload.text, zero for empty text", "number",
     [({"text": "One two three"}, 3), ({"text": ""}, 0)],
     [({"text": " two\n\t words "}, 2), ({"text": "single"}, 1)]),
]


def _case(pair):
    payload, value = pair
    return {"payload": payload, "expected": {"value": value}}


def contracts():
    """Return prompts/contracts and PUBLIC cases only, never heldout oracles."""
    tasks = []
    for i, (name, heading, operation, output_type, public, _holdout) in enumerate(APPS):
        contract = {"id": f"Fullstack/{i:02d}", "slug": name,
                    "route": f"/api/{name}", "heading": heading,
                    "operation": operation, "output_type": output_type,
                    "response_schema": {"data": {"value": output_type}},
                    "ui_testid": f"app-{name}"}
        tasks.append({"task_id": contract["id"], "contract": contract,
                      "public_cases": [_case(pair) for pair in public]})
    return tasks


def holdout_cases():
    """Intentionally called only AFTER candidate search has completed."""
    return {f"Fullstack/{i:02d}": [_case(pair) for pair in spec[5]]
            for i, spec in enumerate(APPS)}


def expected_display(value):
    if value is None:
        return "none"
    if isinstance(value, list):
        return ", ".join(map(str, value))
    return str(value)


def contract_sha256(tasks):
    public = [{"task_id": t["task_id"], "contract": t["contract"],
               "public_cases": t["public_cases"]} for t in tasks]
    data = json.dumps(public, sort_keys=True, separators=(",", ":")).encode()
    return hashlib.sha256(data).hexdigest()


def module_prompt(task, role):
    c = task["contract"]
    if role == "logic":
        return (f"# backend/logic.py - Python 3.11\n"
                f"# Compute: {c['operation']}.\n"
                f"# Input payload is a Python dict; return exactly a dict with key 'value'.\n"
                f"# value type: {c['output_type']}.\n"
                "def transform(payload):\n")
    if role == "api":
        return ("const express = require('express');\n"
                f"// server/index.js: POST {c['route']} accepts JSON payload and responds\n"
                "// HTTP 200 with JSON {data: processor(req.body)}.\n"
                "// processor is a supplied synchronous Python-logic bridge.\n"
                "// Create an Express app with express.json(), register the POST route, return app.\n"
                "function createApp(processor) {\n")
    if role == "ui":
        return ("const React = require('react');\n"
                f"// client/ResultView.jsx: render a <section data-testid='{c['ui_testid']}'>\n"
                f"// containing <h3>{c['heading']}</h3> and <output>VALUE</output>.\n"
                "// data is the object {value: ...} returned by the API.\n"
                "// Render null as 'none', arrays joined by ', ', others as strings.\n"
                "function ResultView({data}) {\n")
    raise ValueError(f"Unknown module role: {role}")


MODULES = ("logic", "api", "ui")
